package cl.uss.ca.external.pure.model;

public class JournalTitleData {
    private Long pureId;
    private String title;

    public Long getPureId() {
        return pureId;
    }

    public void setPureId(Long pureId) {
        this.pureId = pureId;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }
}
